/* World Atlas service worker — offline PWA support.
 *
 * Strategy:
 *   - Precache the app shell and offline fallback.
 *   - Geodata & flags: cache-first (immutable, generated by the pipeline).
 *   - Country pages & navigations: network-first, falling back to cache, then
 *     to the offline page.
 *   - Other GET requests: stale-while-revalidate.
 */

const VERSION = "world-atlas-v1";
const STATIC_CACHE = `${VERSION}-static`;
const DATA_CACHE = `${VERSION}-data`;
const PAGE_CACHE = `${VERSION}-pages`;

const PRECACHE = ["/", "/browse", "/offline", "/data/countries-index.json"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(STATIC_CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => !k.startsWith(VERSION)).map((k) => caches.delete(k))),
    ).then(() => self.clients.claim()),
  );
});

function cacheFirst(request, cacheName) {
  return caches.open(cacheName).then((cache) =>
    cache.match(request).then((hit) => {
      if (hit) return hit;
      return fetch(request).then((res) => {
        if (res.ok) cache.put(request, res.clone());
        return res;
      });
    }),
  );
}

function networkFirst(request, cacheName) {
  return caches.open(cacheName).then((cache) =>
    fetch(request)
      .then((res) => {
        if (res.ok) cache.put(request, res.clone());
        return res;
      })
      .catch(() => cache.match(request).then((hit) => hit || caches.match("/offline"))),
  );
}

function staleWhileRevalidate(request, cacheName) {
  return caches.open(cacheName).then((cache) =>
    cache.match(request).then((hit) => {
      const network = fetch(request).then((res) => {
        if (res.ok) cache.put(request, res.clone());
        return res;
      }).catch(() => hit);
      return hit || network;
    }),
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // don't intercept map tiles / Commons images

  if (url.pathname.startsWith("/data/") || url.pathname.startsWith("/flags/")) {
    event.respondWith(cacheFirst(request, DATA_CACHE));
    return;
  }
  if (request.mode === "navigate" || url.pathname.startsWith("/country/")) {
    event.respondWith(networkFirst(request, PAGE_CACHE));
    return;
  }
  event.respondWith(staleWhileRevalidate(request, STATIC_CACHE));
});
